    const appBase = ($vars.APP_BASE_URL || $vars.FRONTEND_URL || 'https://scalepods-hr-saas-web.vercel.app').replace(/\/+$/, '');
    const accessToken = $node['Code - Generate Candidate Access Token'].json.access_token || '';
    const bookingUrl = appBase + '/book/' + roundId + '?tok=' + accessToken;
    const meetingUrl = cand.meeting_link || 'https://meet.google.com';
    const assignUrl = appBase + '/assignment/' + roundId + '?tok=' + accessToken;
    const schedTime = cand.scheduled_at || 'tomorrow';

    let params = [];
    if (['interview_invite_v1', 'booking_reminder_day1', 'booking_reminder_day3', 'booking_final_notice'].includes(templateName)) {
      params = [
        { type: 'text', text: String(firstName) },
        { type: 'text', text: String(role) },
        { type: 'text', text: String(company) },
        { type: 'text', text: String(bookingUrl) }
      ];
    } else if (templateName === 'pre_interview_24h') {
      params = [
        { type: 'text', text: String(firstName) },
        { type: 'text', text: String(role) },
        { type: 'text', text: String(company) },
        { type: 'text', text: String(schedTime) }
      ];
    } else if (templateName === 'interview_link_today') {
      params = [
        { type: 'text', text: String(firstName) },
        { type: 'text', text: String(role) },
        { type: 'text', text: String(company) },
        { type: 'text', text: String(meetingUrl) }
      ];
    } else if (templateName === 'assignment_reminder_24h') {
      params = [
        { type: 'text', text: String(firstName) },
        { type: 'text', text: String(role) },
        { type: 'text', text: String(company) },
        { type: 'text', text: String(assignUrl) }
      ];
    } else {
      params = [
        { type: 'text', text: String(firstName) },
        { type: 'text', text: String(role) },
        { type: 'text', text: String(company) }
      ];
    }

    return {
      messaging_product: 'whatsapp',
      to: cand.candidate_phone,
      type: 'template',
      template: {
        name: templateName,
        language: { code: tmpl.locale || 'en' },
        components: [
          {
            type: 'body',
            parameters: params
          }
        ]
      }
    };
  })()
}}

parameters.subject:
={{
  (() => {
    const cand = $node["Suppression & Entitlement Check"].json;
    const candName = cand.candidate_name || 'Candidate';
    const firstName = cand.candidate_first_name || 'there';
    const role = cand.role_title || cand.job_title || 'Role';
    const company = cand.company_name || 'ScalePods';
    const stage = String(cand.stage || '').toLowerCase();
    const rawSub = ($node["Supabase - Resolve Email Template"]?.json?.subject || $node["Supabase - Resolve Email Template"]?.json?.[0]?.subject || '');

    if (rawSub && rawSub.trim()) {
      return rawSub
        .replace(/\{\{\s*(?:candidate_name|name|1)\s*\}\}/gi, candName)
        .replace(/\{\{\s*candidate_first_name\s*\}\}/gi, firstName)
        .replace(/\{\{\s*(?:job_title|role|role_title|2)\s*\}\}/gi, role)
        .replace(/\{\{\s*(?:company_name|company|account_name|3)\s*\}\}/gi, company);
    }

    if (stage === 'interview_invite') {
      return `Interview Invitation: ${role} - ${candName} | ${company}`;
    }
    if (stage === 'booking_confirmed') {
      return `Interview Confirmed: ${role} - ${candName} | ${company}`;
    }
    if (['booking_reminder_day1', 'booking_reminder_1'].includes(stage)) {
      return `Reminder: Schedule your ${role} interview - ${candName} | ${company}`;
    }
    if (['booking_reminder_day3', 'booking_reminder_2'].includes(stage)) {
      return `Action Required: Select your interview slot for ${role} - ${candName} | ${company}`;
    }
    if (['booking_final_notice', 'booking_reminder_day5'].includes(stage)) {
      return `Final Notice: Interview scheduling for ${role} - ${candName} | ${company}`;
    }
    if (stage === 'booking_rescheduled') {
      return `Interview Rescheduled: ${role} - ${candName} | ${company}`;
    }
    if (stage === 'pre_interview_24h') {
      return `Interview Reminder (Tomorrow): ${role} - ${candName} | ${company}`;
    }
    if (stage === 'interview_link_today') {
      return `Interview Access Link Today: ${role} - ${candName} | ${company}`;
    }
    if (stage === 'assignment_issued' || stage === 'assignment_invite') {
      return `Practical Assignment: ${role} - ${candName} | ${company}`;
    }
    if (stage === 'assignment_reminder_24h') {
      return `Assignment Deadline Reminder: ${role} - ${candName} | ${company}`;
    }

    return `Interview Update: ${role} - ${candName} | ${company}`;
  })()
}}

