={{
  (() => {
    const cand = $node["Suppression & Entitlement Check"].json;
    const tmpl = $node["Supabase - Resolve Email Template"]?.json || $node["Supabase - Resolve Email Template"]?.json?.[0] || {};
    let rawHtml = tmpl.body_html || '';
    const firstName = cand.candidate_first_name || 'there';
    const candName = cand.candidate_name || 'Candidate';
    const company = cand.company_name || 'ScalePods';
    const role = cand.role_title || cand.job_title || 'the role';
    const appBase = ($vars.APP_BASE_URL || $vars.FRONTEND_URL || 'https://scalepods-hr-saas-web.vercel.app').replace(/\/+$/, '');
    const accessToken = $node['Code - Generate Candidate Access Token'].json.access_token || '';
    const bookingUrl = appBase + '/book/' + (cand.round_instance_id || '') + '?tok=' + accessToken;
    const assignUrl = appBase + '/assignment/' + (cand.round_instance_id || '') + '?tok=' + accessToken;

    if (!rawHtml) {
      return '<p>Hi ' + firstName + ',</p><p>Congratulations on moving forward for the ' + role + ' position at ' + company + '!</p><p>Please book your interview slot using this link: <a href="' + bookingUrl + '">' + bookingUrl + '</a></p>';
    }

    return rawHtml
      .replace(/\{\{1\}\}/g, firstName)
      .replace(/\{\{2\}\}/g, role)
      .replace(/\{\{3\}\}/g, company)
      .replace(/\{\{4\}\}/g, '<a href="' + bookingUrl + '">' + bookingUrl + '</a>')
      .replace(/\{\{booking_link\}\}/g, bookingUrl)
      .replace(/\{\{assignment_link\}\}/g, assignUrl)
      .replace(/\{\{job_title\}\}/g, role)
      .replace(/\{\{role\}\}/g, role)
      .replace(/\{\{role_title\}\}/g, role)
      .replace(/\{\{candidate_first_name\}\}/g, firstName)
      .replace(/\{\{candidate_name\}\}/g, candName)
      .replace(/\{\{account_name\}\}/g, company)
      .replace(/\{\{company_name\}\}/g, company)
      .replace(/\{\{[^}]*candidate[^}]*\}\}/gi, firstName)
      .replace(/\{\{[^}]*account[^}]*\}\}/gi, company);
  })()
}}

