const crypto=require('crypto');
const ctx=$node['Suppression & Entitlement Check'].json;
const data=$node['Supabase - Get Round Instance & Campaign'].json;
const round=Array.isArray(data)?data[0]:data;
const type=round?.round_type==='assignment'||String(ctx.stage||'').startsWith('assignment')?'assignment':(round?.round_type==='human_interview'?'booking':null);
const token=type&&ctx.round_instance_id?crypto.randomBytes(32).toString('hex'):null;
return [{json:{...ctx,access_token:token,access_token_hash:token?crypto.createHash('sha256').update(token).digest('hex'):null,access_token_type:type,access_token_expiry:new Date(Date.now()+30*86400000).toISOString()}}];
